      SUBROUTINE ELCOMPCC     STEPS THROUGH COMPOUND ELEMENTS (RBEND, SBEND, HKICK, VKICK,C     AND KICKER)CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4E.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER         ID, IMIS, IPT, IPTOJM(25), J      LOGICAL         TILINT      REAL            DATARCC     ELEMENTS VKICK AND KICKER ARE TREATED LIKE ROTATED HKICKC      TILT = .FALSE.      IF (TYPE .EQ. 36) THEN        TILT = .TRUE.      ELSE IF (TYPE .EQ. 42) THEN        IF (IPTOJ(3) .NE. 0) THEN          ID = IPTOJ(3)          IF (DATAR(I+ID) .NE. 0.0 .OR. TIE(I+ID) .NE. 0)      1        TILT = .TRUE.        ENDIF      ELSE        IPT = IPTOJ(NTILT)        IF (IPT .NE. 0) THEN          IF (DATAR(I+IPT) .NE. 0.0 .OR. TIE(I+IPT) .NE. 0)      1        TILT = .TRUE.        ENDIF      ENDIF      BEFORE = .TRUE.CC     CHECK FOR MISALIGNMENTSC      DMC = .FALSE.      IF (ALO(1)) THEN        NMIS = NM4        NMISE = NUM4        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LFM = TYT/100        RORC = MOD(TYT,10)        IR = 3        DMC = LFM .GE. 1      ENDIFCC     ENTRANCE MISALIGNMENTC      IF (DMC) THEN        TYPEC = 8        LXRAN = LFM .EQ. 2        DO 50 J = 1, 25   50   IPTOJB(J) = IPTOJ(J)        CALL SKETCH(NMISE)        DO 60 J = 1, 25   60   IPTOJM(J) = IPTOJ(J)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200        DO 70 J = 1, 25   70   IPTOJ(J) = IPTOJB(J)      ENDIF      IF (LFM .EQ. 0 .AND. ALO(1) .AND. R2P) CALL UPDAT2      IF (LFM .EQ. 1 .AND. ALO(1) .AND. OCP(3)) CALL RESET(3)CC     COORDINATE ROTATIONC      LXRAN = .TRUE.      IF (TILT) THEN        TYPEC = 20        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            TILINT = .FALSE.            IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29 .OR. TYPE .EQ. 35      1          .OR. TYPE .EQ. 42) THEN              TILINT = .TRUE.            ELSE IF (TYPE .EQ. 36) THEN              IPT = IPTOJ(NTILT)              IF (IPT .NE. 0.0) THEN                IF (DATA(I+IPT) .NE. 0.0 .OR. TIE(I+IPT) .NE. 0)      1              TILINT = .TRUE.              ENDIF            ENDIF            IF (TILINT) THEN              CALL POSTER              SONLY = .TRUE.              CALL MPRINT              SONLY = .FALSE.            ENDIF          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFCC     ENTRANCE FRINGING FIELDC      TYPEC = 2      IF (NV3 .GE. 1) THEN        CALL DERIVE      ELSE        IF (LAY) CALL CSAVE        CALL ELICIT        IF (.NOT. LSTEPN) THEN          IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) CALL POSTER        ENDIF      ENDIF      IF (FLUSHL) GO TO 200      IF (TYPE .LE. 0) GO TO 200CC     CENTRAL BODY OF BENDC      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) TYPEC = 4      IF (TYPE .EQ. 35 .OR. TYPE .EQ. 36 .OR. TYPE .EQ. 42) TYPEC = 35      IF (NV3 .GE. 1) THEN        CALL DERIVE      ELSE        CALL ELICIT        IF (.NOT. LSTEPN) THEN          CALL POSTER        ENDIF      ENDIF      IF (FLUSHL) GO TO 200      IF (TYPE .LE. 0) GO TO 200CC     EXIT FRINGING FIELDC      TYPEC = 2      BEFORE = .FALSE.      IF (NV3 .GE. 1) THEN        CALL DERIVE      ELSE        CALL ELICIT        IF (.NOT. LSTEPN) THEN          IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) CALL POSTER          CALL VPRINT          IF ((TYPE .EQ. 28 .OR. TYPE .EQ. 29) .AND. LAY .AND. PBP)      1         CALL BPRINT          IF (TILT) THEN            IF (TILINT .OR. TYPE .NE. 36) THEN              IF (TILINT) SONLY = .TRUE.              CALL MPRINT              IF (TILINT) SONLY = .FALSE.            ENDIF          ELSE            CALL MPRINT          ENDIF        ENDIF      ENDIF      IF (FLUSHL) GO TO 200      IF (TYPE .LE. 0) GO TO 200CC     REVERSE ROTATION OF ELEMENTC      IF (TILT) THEN        TYPEC = 20        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            IF (TILINT) CALL POSTER            IF (TILINT .OR. TYPE .EQ. 36) CALL MPRINT          ENDIF         ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .EQ. 0) GO TO 200      ENDIFCC     SEE IF ELEMENT IS MISALIGNEDC      DMC = .FALSE.      IF (ALO(1)) THEN        NMIS = NM4        DMC = .TRUE.      ENDIFCC     EXIT MISALIGNMENTC      IF (DMC) THEN        IF (NV3 .GE. 1) THEN          IF (LFM .EQ. 0 .AND. (R2P .OR. R3P)) CALL UPDAT2        ELSE          IF (LFM .EQ. 0 .AND. R2P) CALL UPDAT2        ENDIF        TYPEC = 8        DO 180 J = 1, 25  180   IPTOJ(J) = IPTOJM(J)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF         IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200         ENDIFC  200 RETURN      END